const t=k=>words[state.language][k]||k;const cats=["mobs", "survival", "creative", "hardcore", "technical", "redstone", "commands", "mods", "building", "secrets", "dimensions", "blocks", "history", "legacy", "earth", "dungeons", "dungeons2", "legends"];const nav=[['home','⌂'],['topics','▦'],['library','▤'],['saved','♧'],['community','＋'],['settings','⚙'],['database','▥']];
function persist(){localStorage.setItem('blockwise',JSON.stringify(state))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function art(id){const f=facts.find(f=>f.id===id),image=f?.image||topicImages[id];if(!image?.src)return '<div class="image-empty">'+t('imagepending')+'</div>';return '<img src="'+esc(image.src)+'" alt="'+esc(image.alt?.[state.language]||image.alt||id)+'" loading="lazy" decoding="async">'}
function factTopics(f){return f.topics||[f.category]}
function tagLabel(id){const tag=taxonomy.tags.find(x=>x.id===id);return tag?.[state.language]||t(id)}
function versionLabel(r){if(r.mode==='unknown')return t('versionunknown');return r.mode==='exact'?r.from:r.from+' – '+(r.to||t('onward'))}
function versionCompare(a,b){const aa=a.split('.').map(Number),bb=b.split('.').map(Number);for(let i=0;i<Math.max(aa.length,bb.length);i++){const d=(aa[i]||0)-(bb[i]||0);if(d)return Math.sign(d)}return 0}
function versionMatches(f){const all=f.versionRanges||[];if(editionFilter==='both'&&!['java','bedrock'].every(ed=>all.some(r=>r.edition===ed)))return false;const ranges=all.filter(r=>editionFilter==='all'||editionFilter==='both'||r.edition===editionFilter);if(!ranges.length)return false;if(!versionFilter)return true;return ranges.some(r=>scopedMatch(r,versionFilter))}
function tagHTML(f,limit=99){return '<div class="fact-tags">'+(f.tags||[]).slice(0,limit).map(id=>'<button type="button" data-filter-tag="'+esc(id)+'">#'+esc(tagLabel(id))+'</button>').join('')+'</div>'}
function versionHTML(f){return '<section class="version-box"><strong>'+t('versions')+'</strong>'+f.versionRanges.map(r=>'<div><b>'+esc(editionName(r.edition))+'</b> · '+esc(versionLabel(r))+(r.verified?'':' · '+t('unverified'))+'</div>').join('')+'<p class="small">'+esc(f.versionNotes?.[state.language]||'')+'</p></section>'}
function render(){document.documentElement.lang=state.language;window.BlockwiseTheme?.apply(state.theme);document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$('#language').textContent=state.language==='en'?'EN / ES':'ES / EN';const n=nav.map(([id,icon])=>'<button data-page="'+id+'" class="'+((page===id||(page==='reference'&&id==='library'))?'active':'')+'"><span>'+icon+'</span>'+t(id)+'</button>').join('');$('#nav').innerHTML=n;$('#mobile-nav').innerHTML=nav.filter(([id])=>['home','library','database'].includes(id)).map(([id,icon])=>'<button data-page="'+id+'" class="'+((page===id||(page==="reference"&&id==="library"))?'active':'')+'"><span>'+icon+'</span>'+t(id)+'</button>').join('')+'<button id="moremenu" class="'+(['topics','saved','community','settings'].includes(page)?'active':'')+'"><span>•••</span>'+t('more')+'</button>';
if(page==='home'||page==='saved')renderFeed();else if(page==='topics')renderTopics();else if(page==='database')renderDatabase();else if(page==='library')renderLibrary();else if(page==='reference')renderReference();else if(page==='settings')renderSettings();else $('#main').innerHTML='<div class="eyebrow">'+t('communitylabel')+'</div><h1>'+t('community')+'</h1><p class="intro">'+t('communityintro')+'</p><div class="panel">'+formHTML()+'</div>';bind();}
let feedList=[],feedObserver;
Object.assign(words.en,{filters:'Filters',caughtup:'You’ve explored every matching fact. Try a new mix or another topic.'});Object.assign(words.es,{filters:'Filtros',caughtup:'Ya exploraste todos los datos que coinciden. Prueba otra mezcla u otro tema.'});
function renderFeed(){
 feedObserver?.disconnect();
 const strip=$('.filterbar')?.scrollLeft||0;
 feedList=matchingFacts();if(page==='home'){feedList=discoveryRank(feedList);rememberDiscovery(feedList)}
 visibleFacts=36;
 $('#main').innerHTML='<div class="feed-heading"><h1>'+t(page==='saved'?'saved':'latest')+'</h1><button id="remix" aria-label="'+t('remix')+'">↻</button></div><div class="feed-tools"><div class="search"><input type="search" id="search" aria-label="'+t('search')+'" placeholder="'+t('search')+'" value="'+esc(query)+'"></div><details class="feed-options"><summary>'+t('filters')+'</summary>'+advancedFilters()+'</details></div><div class="filterbar">'+['all',...cats].map(c=>'<button data-category="'+c+'" class="'+(category===c?'selected':'')+'" aria-pressed="'+(category===c)+'">'+t(c)+'</button>').join('')+'</div><div class="grid feed-grid">'+feedList.slice(0,visibleFacts).map(card).join('')+'</div><div id="feed-end" class="feed-end" aria-live="polite"></div>'+(!feedList.length?'<div class="empty">'+t('nocontent')+'</div>':'');
 $('.filterbar').scrollLeft=strip;
 updateFeedEnd();
 if(typeof IntersectionObserver!=='undefined'){feedObserver=new IntersectionObserver(rows=>{if(rows.some(r=>r.isIntersecting))appendFeed()},{rootMargin:'600px'});feedObserver.observe($('#feed-end'))}
}
function updateFeedEnd(){const more=visibleFacts<feedList.length;$('#feed-end').innerHTML=more?'<button id="next-facts">'+t('loadmore')+'</button>':'<p>'+t('caughtup')+'</p><button id="new-mix">'+t('remix')+'</button>';$('#next-facts')?.addEventListener('click',appendFeed);$('#new-mix')?.addEventListener('click',()=>{remixDiscovery();window.scrollTo(0,0)})}
function appendFeed(){if(page!=='home'&&page!=='saved')return;if(visibleFacts>=feedList.length)return;const next=feedList.slice(visibleFacts,visibleFacts+24);visibleFacts+=next.length;$('.feed-grid').insertAdjacentHTML('beforeend',next.map(card).join(''));bindActions($('.feed-grid'));bindReferenceUI($('.feed-grid'));updateFeedEnd()}

function card(f){const x=f[state.language];return '<article class="card"><div class="art">'+art(f.id)+'<span class="tag">'+t(f.category)+'</span></div><div class="cardbody"><div class="meta">'+t('minute')+(state.read.includes(f.id)?' · ✓ '+t('readmark'):'')+'</div><h3><button class="title-button" data-open="'+f.id+'">'+esc(x.title)+'</button></h3><p>'+esc(x.summary)+'</p>'+'<details class="fact-metadata"><summary>'+t('versions')+' · '+t('tags')+'</summary>'+tagHTML(f,4)+'<p class="small version-mini">'+t('versions')+': '+f.versionRanges.map(r=>esc(editionName(r.edition))+' · '+esc(versionLabel(r))+(r.verified?'':' · '+t('unverified'))).join(' / ')+'</p></details><div class="cardfooter"><button class="read" data-open="'+f.id+'">'+t('read')+' ↗</button><div class="actions"><button data-listen="'+f.id+'" aria-label="'+t('listen')+'">▷</button><button data-save="'+f.id+'" class="'+(state.saved.includes(f.id)?'saved':'')+'" aria-label="'+t('save')+'" aria-pressed="'+state.saved.includes(f.id)+'">'+(state.saved.includes(f.id)?'▣':'♧')+'</button><button data-share="'+f.id+'" aria-label="'+t('share')+'">↗</button></div></div></div></article>'}
function renderTopics(){$('#main').innerHTML='<div class="eyebrow">'+t('curiosity')+'</div><h1>'+t('topics')+'</h1><p class="intro">'+t('topicsintro')+'</p><p class="small">'+t('alltopics')+'</p><div class="topicgrid">'+cats.map(c=>{let f=facts.find(f=>f.category===c);return '<button class="topic '+(state.topics.includes(c)?'selected':'')+'" data-topic="'+c+'" aria-pressed="'+state.topics.includes(c)+'"><div class="art">'+art(c)+'</div><h3>'+t(c)+(state.topics.includes(c)?' ✓':' ＋')+'</h3></button>'}).join('')+'</div><h2>'+t('moblibrary')+'</h2><div class="mob-library">'+(mediaCatalog.assets||[]).filter(a=>taxonomy.tags.some(t=>t.id===a.id&&t.group==='mobs')).map(a=>'<figure><button type="button" data-filter-tag="'+esc(a.id)+'"><img loading="lazy" src="'+esc(a.src)+'" alt="'+esc(tagLabel(a.id))+'"><span>'+esc(tagLabel(a.id))+'</span></button><figcaption><a href="'+esc(a.sourcePage)+'" target="_blank" rel="noopener">Minecraft.net ↗</a></figcaption></figure>').join('')+'</div>'}
function renderSettings(){$('#main').innerHTML='<p><button data-check-updates>'+ (state.language==='es'?'Buscar actualizaciones':'Check for updates')+'</button></p>'+'<div class="eyebrow">'+t('personal')+'</div><h1>'+t('settings')+'</h1><p class="intro">'+t('settingsintro')+'</p><section class="panel"><div class="setting-row"><label for="lang">'+t('language')+'</label><select id="lang"><option value="en" '+(state.language==='en'?'selected':'')+'>English</option><option value="es" '+(state.language==='es'?'selected':'')+'>Español</option></select></div><div class="setting-row"><label for="appearance">'+t('theme')+'</label><select id="appearance"><option value="system" '+(state.theme==='system'?'selected':'')+'>'+t('system')+'</option><option value="light" '+(state.theme==='light'?'selected':'')+'>'+t('light')+'</option><option value="dark" '+(state.theme==='dark'?'selected':'')+'>'+t('dark')+'</option></select></div></section>'+(window.BlockwiseNative?'<section class="panel"><h2>'+t('connection')+'</h2><p>'+t('connectioninfo')+'</p><label for="backendurl">'+t('connectionurl')+'</label><input id="backendurl" type="url" placeholder="https://your-blockwise.workers.dev" value="'+esc(localStorage.getItem('blockwise-api-origin')||'')+'"><button id="connectbackend">'+t('connect')+'</button></section>':'')+'<section class="panel"><h2>'+t('backup')+'</h2><p>'+t('backupinfo')+'</p><button id="export">'+t('export')+'</button><button id="import">'+t('import')+'</button><input type="file" id="file" accept="application/json" hidden><hr><h3>'+t('code')+'</h3><p class="small">'+t('codeinfo')+'</p><input class="code" id="recovery" autocomplete="off" spellcheck="false" aria-label="'+t('code')+'" value="'+esc(localStorage.getItem('blockwise-code')||'')+'"><button id="newcode">'+t('newcode')+'</button><button id="sync">'+t('sync')+'</button><button id="restore">'+t('restore')+'</button><button id="deletecloud">'+t('deletecloud')+'</button><p class="small">'+t('datawarn')+'</p></section><section class="panel"><h2>'+t('apidocs')+'</h2><p><a href="/developers">'+t('apidocs')+' ↗</a></p></section><section class="panel"><h2>'+t('install')+'</h2><p>'+t('installtext')+'</p></section><section class="panel"><h2>'+t('privacy')+'</h2><p>'+t('privacytext')+'</p><button id="reset">'+t('reset')+'</button></section>'}
function openFact(id){const f=facts.find(f=>f.id===id);if(!f)return;if(f.targetId){if(!state.read.includes(id)){state.read.push(id);persist()}navigateEntry(f.targetId,id);return;}const x=f[state.language];if(!state.read.includes(id)){state.read.push(id);persist()}history.replaceState(null,'','#fact/'+id);$('#dialog').innerHTML='<div class="modalbar"><span class="meta">'+t(f.category)+' / '+t('minute')+'</span><button id="close">'+t('close')+' ×</button></div><div class="art">'+art(id)+'</div><div class="modalbody"><div class="eyebrow">'+f.versionRanges.map(r=>esc(editionName(r.edition))).join(' + ')+'</div><h2>'+esc(x.title)+'</h2><p class="lead">'+esc(x.summary)+'</p><div class="actions"><button data-listen="'+id+'">▷ '+t('listen')+'</button><button data-stop>■ '+t('stop')+'</button><button data-save="'+id+'">♧ '+t('save')+'</button><button data-share="'+id+'">↗ '+t('share')+'</button></div>'+tagHTML(f)+versionHTML(f)+x.body.map(b=>'<p>'+esc(b)+'</p>').join('')+imageCredit(f)+'<section class="source"><strong>'+t('source')+'</strong><p>'+t('sourceinfo')+'</p><a href="'+esc(f.source)+'" target="_blank" rel="noopener">'+esc(f.source)+' ↗</a></section><p class="warning">'+t(f.status==='indexed'?'indexed':'partial')+'</p><button data-report="'+id+'">⚑ '+t('report')+'</button></div>';$('#dialog').showModal();bindDialog();}
function bindDialog(){const d=$('#dialog');d.querySelector('#close')?.addEventListener('click',()=>d.close());bindActions(d);d.querySelector('[data-report]')?.addEventListener('click',e=>{const f=facts.find(f=>f.id===e.currentTarget.dataset.report);d.innerHTML='<div class="modalbar"><strong>'+t('report')+'</strong><button id="close">'+t('close')+' ×</button></div><div class="modalbody">'+formHTML(f)+'</div>';bindDialog();bindForm(d)})}
function bindActions(root){root.querySelectorAll('[data-filter-tag]').forEach(b=>b.onclick=()=>{selectedTag=b.dataset.filterTag;page=page==='database'?'database':'home';category='all';if($('#dialog').open)$('#dialog').close();render();window.scrollTo(0,0)});root.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>{if(e?.ctrlKey||e?.metaKey||e?.shiftKey)return;e?.preventDefault();openFact(b.dataset.open)});root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(v=>v!==id):[...state.saved,id];persist();render();root.querySelectorAll('[data-save="'+id+'"]').forEach(n=>{n.classList.toggle('saved',state.saved.includes(id));n.setAttribute('aria-pressed',state.saved.includes(id))});toast(t('savedtoast'))});root.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>speak(b.dataset.listen));root.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>window.speechSynthesis?.cancel());root.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{const f=facts.find(f=>f.id===b.dataset.share),url=location.origin+'/app/#fact/'+f.id,text=f[state.language].summary+'\n'+f.source;try{if(navigator.share)await navigator.share({title:f[state.language].title,text,url});else{await navigator.clipboard.writeText(text+'\n'+url);toast(t('copied'))}}catch{}})}
function speak(id){if(!window.speechSynthesis){toast(t('noaudio'));return}speechSynthesis.cancel();const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.startsWith(state.language));if(!voice){toast(t('noaudio'));return}const f=facts.find(f=>f.id===id)[state.language],u=new SpeechSynthesisUtterance([f.title,f.summary,...f.body].join('. '));u.lang=state.language==='es'?'es-ES':'en-US';u.voice=voice;u.rate=.95;speechSynthesis.speak(u)}
function bind(){bindFilters();bindCatalog();bindReferenceUI($('#main'));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;category='all';query='';selectedTag='';history.replaceState(null,'','#'+page);render();window.scrollTo(0,0)});bindActions($('#main'));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{const c=b.dataset.topic;state.topics=state.topics.includes(c)?state.topics.filter(v=>v!==c):[...state.topics,c];persist();render()});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$('#random')?.addEventListener('click',()=>openFact(facts[Math.floor(Math.random()*facts.length)].id));bindForm($('#main'));$('#lang')?.addEventListener('change',e=>{state.language=e.target.value;persist();render()});$('#appearance')?.addEventListener('change',e=>{state.theme=e.target.value;persist();render()});$('#connectbackend')?.addEventListener('click',()=>{try{const url=new URL($('#backendurl').value.trim());if(url.protocol!=='https:')throw 0;localStorage.setItem('blockwise-api-origin',url.origin);toast(t('connected'))}catch{toast('https://…')}});$('#newcode')?.addEventListener('click',()=>{const code=Array.from(crypto.getRandomValues(new Uint8Array(24))).map(x=>x.toString(16).padStart(2,'0')).join('');$('#recovery').value=code;localStorage.setItem('blockwise-code',code)});$('#recovery')?.addEventListener('change',e=>localStorage.setItem('blockwise-code',e.target.value.trim()));$('#sync')?.addEventListener('click',()=>cloud('PUT'));$('#restore')?.addEventListener('click',()=>cloud('GET'));$('#deletecloud')?.addEventListener('click',()=>cloud('DELETE'));$('#export')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='blockwise-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});$('#import')?.addEventListener('click',()=>$('#file').click());$('#file')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file||file.size>1024*1024)throw 0;state=validate(JSON.parse(await file.text()));persist();render();toast(t('imported'))}catch{toast(t('badbackup'))}});$('#reset')?.addEventListener('click',()=>{if(confirm(t('resetconfirm'))){state={...initial,saved:[],read:[],topics:[]};persist();localStorage.removeItem('blockwise-code');render()}})}
function validate(o){if(!o||!Array.isArray(o.saved)||!Array.isArray(o.read)||!Array.isArray(o.topics)||!['en','es'].includes(o.language)||!['system','light','dark'].includes(o.theme))throw Error();const ids=facts.map(f=>f.id);return {language:o.language,theme:o.theme,saved:[...new Set(o.saved.filter(v=>ids.includes(v)))],read:[...new Set(o.read.filter(v=>ids.includes(v)))],topics:[...new Set(o.topics.filter(v=>cats.includes(v)))]}}
async function cloud(method){const code=$('#recovery').value.trim();if(!/^[a-f0-9]{48}$/.test(code)){toast(t('syncerror'));return}if(method==='GET'&&!confirm(t('datawarn')+' '+t('restore')+'?'))return;if(method==='DELETE'&&!confirm(t('deletecloud')+'?'))return;localStorage.setItem('blockwise-code',code);try{const r=await fetch('/api/progress',{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+code},...(method==='PUT'?{body:JSON.stringify(state)}:{})});if(!r.ok){toast(t(r.status===404?'notfound':'syncerror'));return}if(method==='GET'){state=validate(await r.json());persist();render()}toast(t(method==='PUT'?'success':method==='DELETE'?'deleted':'restored'))}catch{toast(t('syncerror'))}}
function advancedFilters(){return '<details class="advanced-filters" '+(selectedTag||editionFilter!=='all'||versionFilter?'open':'')+'><summary>'+t('morefilters')+(selectedTag?' · #'+esc(tagLabel(selectedTag)):'')+'</summary><div class="filter-fields"><label>'+t('tags')+'<input id="tagfilter" list="tagchoices" placeholder="'+t('tagsearch')+'" value="'+esc(selectedTag?tagLabel(selectedTag):'')+'"><datalist id="tagchoices">'+taxonomy.tags.map(x=>'<option value="'+esc(x[state.language])+'">'+esc(x.id)+'</option>').join('')+'</datalist></label><label>'+t('editionfilter')+'<select id="editionfilter"><option value="all">'+t('allEditions')+'</option>'+editionOptions(editionFilter)+'<option value="both" '+(editionFilter==='both'?'selected':'')+'>'+t('both')+'</option>'+'</select></label><label>'+t('versionfilter')+'<input id="versionfilter" list="filterbuilds" placeholder="'+t('custombuild')+'" value="'+esc(versionFilter)+'"></label></div><p class="small">'+t('versionhint')+'</p><label class="check-label"><input type="checkbox" id="includeunknown" '+(includeUnknown?'checked':'')+'>'+t('includeunknown')+'</label><button type="button" id="clearfilters">'+t('clearfilters')+'</button></details>'}
function bindFilters(){$('#tagfilter')?.addEventListener('change',e=>{const q=e.target.value.trim().toLowerCase(),tag=taxonomy.tags.find(x=>x.id===q||x.en.toLowerCase()===q||x.es.toLowerCase()===q);selectedTag=tag?.id||q;render()});$('#editionfilter')?.addEventListener('change',e=>{editionFilter=e.target.value;versionFilter='';render()});$('#versionfilter')?.addEventListener('change',e=>{versionFilter=e.target.value.trim();render()});$('#includeunknown')?.addEventListener('change',e=>{includeUnknown=e.target.checked;render()});$('#clearfilters')?.addEventListener('click',()=>{selectedTag='';editionFilter='all';versionFilter='';includeUnknown=false;category='all';render()})}
function imageCredit(f){return f.image?'<p class="image-credit">'+t('imagecredit')+': '+esc(f.image.credit)+' · <a href="'+esc(f.image.sourcePage)+'" target="_blank" rel="noopener">'+t('sourceimage')+' ↗</a></p>':''}
let versionRowNumber=0;
function versionRow(r={edition:'java',mode:'exact',from:'',to:''}){const id='buildlist-'+(++versionRowNumber);return '<div class="version-row"><label>'+t('editionfilter')+'<select class="v-edition">'+editionOptions(r.edition)+'<option value="both">'+t('both')+'</option></select></label><label>'+t('versionmode')+'<select class="v-mode">'+['exact','range','unknown'].map(m=>'<option value="'+m+'" '+(r.mode===m?'selected':'')+'>'+t(m)+'</option>').join('')+'</select></label><label>'+t('versionfrom')+'<input class="v-from" list="'+id+'" maxlength="80" placeholder="'+t('custombuild')+'" value="'+esc(r.from||'')+'"></label><label>'+t('versionto')+'<input class="v-to" list="'+id+'" maxlength="80" value="'+esc(r.to||'')+'"></label><div class="row-build-list">'+versionChoices(r.edition,id)+'</div><button type="button" data-remove-version aria-label="'+t('remove')+'">×</button></div>'}
function formHTML(f){return '<p>'+t('formintro')+'</p><form id="submission"><label>'+t('kind')+'<select name="kind"><option value="'+(f?'report':'suggestion')+'">'+t(f?'report':'suggest')+'</option>'+(!f?'<option value="report">'+t('report')+'</option>':'')+'</select></label><label>'+t('fact')+'<input name="fact" maxlength="300" required value="'+esc(f?f[state.language].summary:'')+'"></label><label>'+t('url')+'<input type="url" name="source" required maxlength="500" placeholder="https://minecraft.wiki/w/…" value="'+esc(f?f.source:'')+'"></label><fieldset><legend>'+t('topicselect')+'</legend><div class="topic-checks">'+cats.map(c=>'<label class="check-label"><input type="checkbox" name="topics" value="'+c+'" '+(f&&factTopics(f).includes(c)?'checked':'')+'>'+t(c)+'</label>').join('')+'</div></fieldset><fieldset><legend>'+t('tags')+'</legend><input id="tagpickersearch" type="search" placeholder="'+t('tagsearch')+'" aria-label="'+t('tagsearch')+'"><div class="tag-picker">'+taxonomy.tags.map(x=>'<label class="tag-choice" data-tag-name="'+esc([x.id,x.en,x.es].join(' ').toLowerCase())+'"><input type="checkbox" name="tags" value="'+esc(x.id)+'" '+(f?.tags.includes(x.id)?'checked':'')+'>'+esc(x[state.language])+'</label>').join('')+'</div><label>'+t('customtags')+'<input name="customTags" maxlength="600" placeholder="speedrunning, storage, farms"></label><p class="small">'+t('customtaghint')+'</p></fieldset><fieldset><legend>'+t('versions')+'</legend><div id="versionrows">'+(f?.versionRanges||[{edition:'java',mode:'exact',from:'',to:''}]).map(versionRow).join('')+'</div><button type="button" id="addversion">＋ '+t('addversion')+'</button><p class="small">'+t('versionformat')+'</p><label>'+t('versionnotes')+'<textarea name="versionNotes" maxlength="1000">'+esc(f?.versionNotes?.[state.language]||'')+'</textarea></label><label>'+t('moddetails')+'<input name="modDetails" maxlength="300"></label></fieldset><label>'+t('details')+'<textarea name="details" required maxlength="3000"></textarea></label><fieldset><legend>'+t('screenshots')+'</legend><p class="small">'+t('medialimits')+'</p><input name="media" id="mediafiles" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm" multiple><div id="mediapreview" class="media-preview"></div><label>'+t('mediacredit')+'<input name="mediaCredit" maxlength="200"></label><label>'+t('mediasource')+'<input name="mediaSource" type="url" maxlength="500" placeholder="https://…"></label><label class="check-label"><input type="checkbox" name="mediaRights">'+t('mediarights')+'</label><p class="small">'+t('reviewonly')+'</p></fieldset><input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><input type="hidden" name="factId" value="'+(f?f.id:'')+'"><p class="small">'+t('submitted')+'</p><button type="submit" class="primary">'+t('send')+' →</button><p id="formstatus" role="status"></p></form>'}
let mediaPreviewURLs=[];
function releaseMediaPreviews(){mediaPreviewURLs.forEach(u=>URL.revokeObjectURL(u));mediaPreviewURLs=[]}
function validFiles(files){const allowed={'image/jpeg':5,'image/png':5,'image/webp':5,'image/gif':5,'video/mp4':25,'video/webm':25};return files.length<=4&&files.reduce((n,f)=>n+f.size,0)<=30*1024*1024&&files.every(f=>allowed[f.type]&&f.size>0&&f.size<=allowed[f.type]*1024*1024)}
function normalizeTag(s){return s.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40)}
function validRange(r){const release=/^\d+(\.\d+){1,3}$/,label=/^[a-zA-Z0-9][^\u0000-\u001f\u007f<>]{0,79}$/;if(!versionCatalog.editions.some(e=>e.id===r.edition)||!['exact','range','unknown'].includes(r.mode))return false;if(r.mode==='unknown')return !r.from&&!r.to;if(r.mode==='exact')return label.test(r.from)&&!r.to;return label.test(r.from)&&(!r.to||(label.test(r.to)&&(!release.test(r.from)||!release.test(r.to)||versionCompare(r.from,r.to)<=0)))}
function bindForm(root){const form=root.querySelector('#submission');if(!form)return;
form.querySelector('#tagpickersearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();form.querySelectorAll('.tag-choice').forEach(n=>n.hidden=!n.dataset.tagName.includes(q))});
const bindRows=()=>{form.querySelectorAll('[data-remove-version]').forEach(b=>b.onclick=()=>{if(form.querySelectorAll('.version-row').length>1)b.closest('.version-row').remove()});form.querySelectorAll('.v-mode').forEach(s=>{const update=()=>{const row=s.closest('.version-row'),unknown=s.value==='unknown',range=s.value==='range';row.querySelector('.v-from').disabled=unknown;row.querySelector('.v-to').disabled=!range};s.onchange=update;update()});form.querySelectorAll('.v-edition').forEach(s=>s.onchange=()=>{const row=s.closest('.version-row'),id=row.querySelector('.v-from').getAttribute('list');row.querySelector('.row-build-list').innerHTML=versionChoices(s.value==='both'?'all':s.value,id)})};bindRows();form.querySelector('#addversion').onclick=()=>{if(form.querySelectorAll('.version-row').length>=24)return;form.querySelector('#versionrows').insertAdjacentHTML('beforeend',versionRow());bindRows()};
form.querySelector('#mediafiles').onchange=e=>{releaseMediaPreviews();const files=Array.from(e.target.files||[]);if(!validFiles(files)){e.target.value='';toast(t('mediaerror'));form.querySelector('#mediapreview').innerHTML='';return}form.querySelector('#mediapreview').innerHTML=files.map(f=>{const url=URL.createObjectURL(f);mediaPreviewURLs.push(url);return '<figure>'+(f.type.startsWith('video/')?'<video controls preload="metadata" src="'+url+'"></video>':'<img alt="'+t('preview')+'" src="'+url+'">')+'<figcaption>'+esc(f.name)+'</figcaption></figure>'}).join('')};
form.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f);let u;try{u=new URL(fd.get('source'))}catch{}if(!u||u.protocol!=='https:'||!(u.hostname==='minecraft.wiki'||u.hostname.endsWith('.minecraft.wiki'))){toast(t('invalid'));return}
const ranges=Array.from(f.querySelectorAll('.version-row')).map(row=>{const mode=row.querySelector('.v-mode').value;return {edition:row.querySelector('.v-edition').value,mode,from:mode==='unknown'?'':row.querySelector('.v-from').value.trim(),to:mode==='range'?row.querySelector('.v-to').value.trim():'',verified:false}}).flatMap(r=>r.edition==='both'?['java','bedrock'].map(edition=>({...r,edition})):r),tags=[...new Set([...fd.getAll('tags'),...String(fd.get('customTags')||'').split(',').map(normalizeTag)].filter(Boolean))],topics=fd.getAll('topics'),files=Array.from(f.querySelector('#mediafiles').files||[]);
if(!topics.length||!tags.length||tags.length>30||!ranges.length||ranges.length>24||!ranges.every(validRange)){toast(t('requiredmeta')+' '+t('versionformat'));return}if(!validFiles(files)||(files.length&&!fd.get('mediaRights'))){toast(t('mediaerror'));return}
const data={kind:fd.get('kind'),fact:fd.get('fact'),source:u.href,details:fd.get('details'),factId:fd.get('factId'),website:fd.get('website'),language:state.language,topics,tags,versionRanges:ranges,versionNotes:fd.get('versionNotes'),modDetails:fd.get('modDetails'),mediaCredit:fd.get('mediaCredit'),mediaSource:fd.get('mediaSource'),mediaRights:!!fd.get('mediaRights')};const body=new FormData();body.set('payload',JSON.stringify(data));files.forEach(file=>body.append('media',file));const btn=f.querySelector('button[type=submit]');btn.disabled=true;btn.textContent=t('submitting');try{const r=await fetch('/api/submissions',{method:'POST',body});if(!r.ok)throw Error();f.reset();releaseMediaPreviews();f.querySelector('#mediapreview').innerHTML='';bindRows();f.querySelector('#formstatus').textContent=t('sent')}catch{f.querySelector('#formstatus').textContent=t('failed')}finally{btn.disabled=false;btn.textContent=t('send')+' →'}})}

$('#language').onclick=()=>{state.language=state.language==='en'?'es':'en';window.speechSynthesis?.cancel();if($('#dialog').open)$('#dialog').close();persist();render()};$('#theme').onclick=()=>{state.theme=({system:'light',light:'dark',dark:'system'})[state.theme]||'system';persist();render()};$('#dialog').addEventListener('close',()=>{if(suppressDialogClose){suppressDialogClose=false;return}releaseMediaPreviews();window.speechSynthesis?.cancel();history.replaceState(null,'','#'+page);render()});
Promise.all(['/facts.json','/taxonomy.json','/media-catalog.json','/entries.json','/versions.json','/catalog-supplement.json'].map(u=>fetch(u).then(r=>r.json()))).then(([data,tax,media,referenceEntries,versions,supplement])=>{facts=[...data,...supplement.facts];versions.editions.push(...supplement.editions);entries=referenceEntries;versionCatalog=versions;prepareReferences();taxonomy=tax;mediaCatalog=media;topicImages=media.topics||{};topicImages.history=facts.find(f=>f.category==='history')?.image;try{state=validate(state)}catch{state={...initial}}const hash=location.hash;page=nav.some(n=>'#'+n[0]===hash)?hash.slice(1):'home';render();if(restoreReferenceRoute())return;if(hash.startsWith('#fact/'))openFact(hash.slice(6))}).catch(()=>{$('#main').textContent='Could not load the collection. Please reconnect and reload. / No se pudo cargar. Conéctate y recarga.'});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

if(window.addEventListener){window.addEventListener('popstate',()=>{if(!restoreReferenceRoute()){page=nav.some(n=>'#'+n[0]===location.hash)?location.hash.slice(1):'home';render()}});window.addEventListener('keydown',e=>{if(e.key==='Escape')hideReferencePreview()});}
